BEGIN TRANSACTION;
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "dealer_applications" ("id" integer primary key autoincrement not null, "business_name" varchar not null, "contact_person" varchar not null, "phone" varchar not null, "email" varchar, "city" varchar not null, "showroom_space" varchar, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "product_colors" ("id" integer primary key autoincrement not null, "product_id" integer not null, "color_name" varchar not null, "hex_code" varchar not null, "accent_hex" varchar, "image_url" varchar, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_features" ("id" integer primary key autoincrement not null, "product_id" integer not null, "title" varchar, "description" text, "image_url" varchar, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "product_specifications" ("id" integer primary key autoincrement not null, "product_id" integer not null, "spec_group" varchar not null, "spec_key" varchar not null, "spec_value" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("product_id") references "products"("id") on delete cascade);
CREATE TABLE "products" ("id" integer primary key autoincrement not null, "slug" varchar not null, "name" varchar not null, "tagline" varchar, "category" varchar not null, "category_key" varchar not null, "price_npr" integer not null, "engine" varchar, "power" varchar, "torque" varchar, "top_speed" varchar, "fuel_system" varchar, "braking" varchar, "warranty" varchar, "mileage" varchar, "description" text, "image" varchar, "badge" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "test_rides" ("id" integer primary key autoincrement not null, "full_name" varchar not null, "phone" varchar not null, "email" varchar not null, "city" varchar not null, "model_id" varchar not null, "ride_date" date not null, "need_finance" tinyint(1) not null default '0', "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "products_slug_unique" on "products" ("slug");
DELETE FROM "sqlite_sequence";
COMMIT;
