INSERT INTO "product_features" VALUES(1,1,'Under-Seat Storage','The Django 125cc features generous under-seat storage that easily fits a jet helmet, combined with a lockable dual glove box and integrated 12V socket for ultimate daily convenience.','https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=800&q=80','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "product_features" VALUES(2,1,'Comfort & Practicality','The Peugeot Django 125cc is designed with optimal rider ergonomics, featuring a plush dual-tone ribbed saddle, spacious legroom, and effortless maneuvering through busy Kathmandu traffic.','https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=800&q=80','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "product_features" VALUES(3,1,'Iconic Neo-Retro Design','Tribute to the legendary 1955 S55 scooter. Featuring polished chrome mirrors, lion signature headlights, vintage motorsports numbers, and French luxury styling.','https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=800&q=80','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "product_features" VALUES(4,3,'Twin LED Projector Headlights','Instantly recognizable on the road, the Speedfight features twin ultra-bright LED projector headlights with 508-inspired lion fang DRL daytime running lights.','https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=800&q=80','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "product_features" VALUES(5,3,'Full Digital LCD Cockpit Display','Comprehensive digital instrument panel displaying speed, trip distance, fuel range, battery level, maintenance alerts, and integrated RAM smartphone holder support.','https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=800&q=80','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "product_features" VALUES(6,3,'A Legacy Of Sport DNA & Handling','Engineered with lightweight sport lattice chassis and Showa gas rear suspension for unmatched precision cornering and high-speed stability.','https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=800&q=80','2026-09-12 13:35:48','2026-09-12 13:35:48');
