INSERT INTO "products" VALUES(1,'django-125-caferacer','Django 125cc Caferacer','Born from 1898 Motorsports Heritage','Neo-Retro (Django)','django',395000,'125 cc EasyMotion EURO-5 EFI','10.6 HP @ 8,000 RPM','9.3 Nm @ 6,500 RPM','95 km/h','EFI (Electronic Fuel Injection)','ABS Front Disc & Rear SBC','3 Years / 30,000 KM','43 km/L','The Peugeot Django 125cc Caferacer is a neo-retro scooter that combines vintage motorsports elegance with modern performance, ideal for riders seeking style, comfort, and everyday practical agility.','https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=1000&q=80','Special Motorsports Edition','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "products" VALUES(2,'django-125-classic','Django 125cc Classic','The Neo-Retro Icon of French Elegance','Neo-Retro (Django)','django',370000,'125 cc 4-Stroke Air-Cooled EURO-5','10.6 HP @ 8,000 RPM','9.3 Nm @ 6,500 RPM','95 km/h','EFI (Electronic Fuel Injection)','SBC Synchro Disc Brakes','3 Years / 30,000 KM','45 km/L','Inspired by the legendary 1955 Peugeot S55, the Django 125 Classic combines vintage French retro aesthetics with EURO-5 EasyMotion EFI technology.','https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=1000&q=80','Most Popular in Kathmandu','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "products" VALUES(3,'speedfight-4-sport','Speedfight 4+ Sport 125/150','Pure Racing DNA for Urban Conquerors','Sport / Street (Speedfight)','speedfight',345000,'125 cc / 150 cc SmartMotion Liquid Cooled','11.0 HP / 14.5 HP','10.8 Nm / 13.2 Nm','100 km/h','EFI (Electronic Fuel Injection)','Dual SBC Wave Discs','3 Years / 30,000 KM','42 km/L','The 4th generation of Europe''s iconic sport scooter line. Equipped with twin LED projector headlamps inspired by Peugeot 508 lion fangs, LCD digital instrument cluster, RAM smartphone mount, and Showa gas suspension.','https://images.unsplash.com/photo-1558981806-ec527fa84c39?auto=format&fit=crop&w=1000&q=80','Best Sport Scooter','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "products" VALUES(4,'xp400-gt-maxi','XP400 GT Maxi Adventure','The Ultimate Premium Adventure Crossover','Maxi / Adventure (XP400 / Tweet)','xp400',1450000,'400 cc PowerMotion EURO-5 Liquid Cooled','36.7 HP @ 8,150 RPM','38.1 Nm @ 5,400 RPM','140 km/h','EFI (Electronic Fuel Injection)','Dual Channel ABS + 295mm Twin Wave Discs','3 Years / 50,000 KM','26 km/L','Made in France at Mandeure. The XP400 GT combines high-end GT luxury with adventure capability. Features spoked wheels with Pirelli tires, keyless smart ignition, twin 295mm front wave disc brakes, and full i-Connect navigation.','https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?auto=format&fit=crop&w=1000&q=80','Flagship Luxury Crossover','2026-09-12 13:35:48','2026-09-12 13:35:48');
INSERT INTO "products" VALUES(5,'tweet-125-gt','Tweet 125 GT Urban','Agile High-Wheel Comfort for Kathmandu City','Maxi / Adventure (XP400 / Tweet)','xp400',315000,'125 cc EasyMotion EURO-5 EFI','11.5 HP @ 8,500 RPM','10.2 Nm @ 6,500 RPM','96 km/h','EFI (Electronic Fuel Injection)','SBC Front & Rear Disc','3 Years / 30,000 KM','46 km/L','Specifically engineered for cobblestone and uneven city surfaces. Large 16-inch alloy wheels deliver superior stability, while its compact turning radius and flat deck make daily commuting effortlessly smooth.','https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=1000&q=80','Urban Commuter Choice','2026-09-12 13:35:48','2026-09-12 13:35:48');
